/**
 * Generates supabase/seed.sql from the in-code trade catalog so the database and the app agree.
 * Run: npx tsx scripts/gen-seed.ts
 */
import { writeFileSync } from "node:fs";
import { trades } from "../src/lib/trades/catalog";
import { PROVIDER_CATALOG } from "../src/lib/pricing/provider";

const q = (s: string | null | undefined) => (s == null ? "null" : `'${String(s).replace(/'/g, "''")}'`);
const lines: string[] = [
  "-- GENERATED by scripts/gen-seed.ts. Do not edit by hand. Safe to re-run (idempotent).",
  "-- Reference data only: no users, no prices.",
  "begin;",
  "",
  "insert into public.trade_categories (slug, name, icon, family, featured, sort_order, active) values",
  trades.map((t, i) => `  (${q(t.slug)}, ${q(t.name)}, ${q(t.icon)}, ${q(t.family)}, ${t.featured ? "true" : "false"}, ${i}, true)`).join(",\n"),
  "on conflict (slug) do update set name = excluded.name, icon = excluded.icon, family = excluded.family, featured = excluded.featured, sort_order = excluded.sort_order;",
  "",
  "insert into public.trade_templates (trade_slug, version, definition, published) values",
  trades.map((t) => `  (${q(t.slug)}, ${t.template.version}, ${q(JSON.stringify({ groups: t.template.groups, examples: t.template.examples }))}::jsonb, true)`).join(",\n"),
  "on conflict (trade_slug, version) do nothing;",
  "",
  "insert into public.feature_flags (key, enabled, description) values",
  "  ('website_import', true, 'Allow importing branding from a website URL. When off, users enter details manually.')",
  "on conflict (key) do nothing;",
  "",
  "-- Pricing sources are listed but DISABLED: none is licensed or connected yet.",
  "insert into public.pricing_sources (id, display_name, kind, enabled) values",
  PROVIDER_CATALOG.map((p) => `  (${q(p.id)}, ${q(p.name)}, ${q(p.kind)}, false)`).join(",\n"),
  "on conflict (id) do nothing;",
  "",
  "commit;",
  "",
];
writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`seed.sql: ${trades.length} trades`);
